from __future__ import annotations

import json
from dataclasses import dataclass

import pytest
from pytest_codspeed.plugin import BenchmarkFixture

from benchmarks._utils import ASGIRunner, ChunkedReceive
from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.types import ASGIApp, Message, Receive, Scope, Send

KiB = 1024


@dataclass(frozen=True)
class JSONCase:
    name: str
    items: int


@dataclass(frozen=True)
class RequestCase:
    payload: JSONCase
    chunk_size: int | None

    @property
    def id(self) -> str:
        chunk_size = "single" if self.chunk_size is None else f"{self.chunk_size // KiB}KiB"
        return f"{self.payload.name}-{chunk_size}"


def make_content(case: JSONCase) -> list[dict[str, object]]:
    return [{"id": index, "name": f"item-{index}", "enabled": index % 2 == 0} for index in range(case.items)]


def render_json(content: list[dict[str, object]]) -> bytes:
    return json.dumps(content, ensure_ascii=False, allow_nan=False, separators=(",", ":")).encode()


SMALL_PAYLOAD = JSONCase("1KiB", 25)
LARGE_PAYLOAD = JSONCase("1MiB", 22_000)
PAYLOADS = (SMALL_PAYLOAD, LARGE_PAYLOAD)
REQUEST_CASES = (
    RequestCase(SMALL_PAYLOAD, None),
    RequestCase(LARGE_PAYLOAD, None),
    RequestCase(LARGE_PAYLOAD, 64 * KiB),
)


class RequestJSONApp:
    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        content = await Request(scope, receive).json()
        await send_result(send, str(len(content)).encode())


class JSONResponseApp:
    def __init__(self, content: list[dict[str, object]]) -> None:
        self.content = content

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        await JSONResponse(self.content)(scope, receive, send)


async def send_result(send: Send, body: bytes) -> None:
    await send({"type": "http.response.start", "status": 200, "headers": []})
    await send({"type": "http.response.body", "body": body})


REQUEST_APP = RequestJSONApp()


def http_scope(method: str, headers: list[tuple[bytes, bytes]]) -> Scope:
    return {
        "type": "http",
        "asgi": {"version": "3.0", "spec_version": "2.5"},
        "http_version": "1.1",
        "method": method,
        "scheme": "http",
        "path": "/",
        "raw_path": b"/",
        "root_path": "",
        "query_string": b"",
        "headers": headers,
        "client": ("127.0.0.1", 50000),
        "server": ("127.0.0.1", 80),
    }


def make_chunks(body: bytes, chunk_size: int | None) -> tuple[bytes, ...]:
    if chunk_size is None:
        return (body,)
    return tuple(body[offset : offset + chunk_size] for offset in range(0, len(body), chunk_size))


def dispatch_request(runner: ASGIRunner, chunks: tuple[bytes, ...]) -> list[Message]:
    scope = http_scope("POST", [(b"content-type", b"application/json")])
    return runner.run(REQUEST_APP, scope, ChunkedReceive(chunks))


def dispatch_response(runner: ASGIRunner, app: ASGIApp) -> list[Message]:
    return runner.run(app, http_scope("GET", []))


@pytest.fixture(scope="module", autouse=True)
def warm_apps(asgi_runner: ASGIRunner) -> None:
    content = make_content(SMALL_PAYLOAD)
    chunks = (render_json(content),)
    app = JSONResponseApp(content)
    for _ in range(100):
        dispatch_request(asgi_runner, chunks)
        dispatch_response(asgi_runner, app)


@pytest.mark.parametrize("case", REQUEST_CASES, ids=lambda case: case.id)
@pytest.mark.benchmark(max_time=0.5, max_rounds=1)
def test_request_json(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture, case: RequestCase) -> None:
    body = render_json(make_content(case.payload))
    chunks = make_chunks(body, case.chunk_size)
    messages = benchmark.pedantic(dispatch_request, args=(asgi_runner, chunks), rounds=1)

    assert messages == [
        {"type": "http.response.start", "status": 200, "headers": []},
        {"type": "http.response.body", "body": str(case.payload.items).encode()},
    ]
    benchmark.extra_info["body_bytes"] = len(body)
    benchmark.extra_info["chunk_bytes"] = case.chunk_size or len(body)
    benchmark.extra_info["chunks"] = len(chunks)
    benchmark.extra_info["items"] = case.payload.items


@pytest.mark.parametrize("payload", PAYLOADS, ids=lambda payload: payload.name)
@pytest.mark.benchmark(max_time=0.5, max_rounds=1)
def test_json_response(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture, payload: JSONCase) -> None:
    content = make_content(payload)
    body = render_json(content)
    messages = benchmark.pedantic(
        dispatch_response,
        args=(asgi_runner, JSONResponseApp(content)),
        rounds=1,
    )

    assert messages == [
        {
            "type": "http.response.start",
            "status": 200,
            "headers": [
                (b"content-length", str(len(body)).encode()),
                (b"content-type", b"application/json"),
            ],
        },
        {"type": "http.response.body", "body": body},
    ]
    benchmark.extra_info["body_bytes"] = len(body)
    benchmark.extra_info["items"] = payload.items

from __future__ import annotations

from pytest_codspeed.plugin import BenchmarkFixture

from benchmarks._utils import ASGIRunner
from starlette.requests import Request
from starlette.responses import PlainTextResponse
from starlette.routing import Route, Router
from starlette.types import ASGIApp, Message, Scope


async def endpoint(request: Request) -> PlainTextResponse:
    return PlainTextResponse("ok")


def build_router(groups: int) -> Router:
    routes: list[Route] = []
    for i in range(groups):
        routes.extend(
            [
                Route(f"/resources{i}", endpoint, methods=["GET", "POST"]),
                Route(f"/resources{i}/{{id:int}}", endpoint, methods=["GET", "PUT", "DELETE"]),
                Route(f"/resources{i}/{{id:int}}/items", endpoint, methods=["GET", "POST"]),
                Route(f"/resources{i}/{{id:int}}/items/{{item}}", endpoint, methods=["GET"]),
            ]
        )
    return Router(routes=routes)


LARGE_ROUTER = build_router(groups=30)  # 120 routes
SMALL_ROUTER = build_router(groups=5)  # 20 routes


def http_scope(method: str, path: str) -> Scope:
    # Built per dispatch: the router mutates the scope while matching, so a
    # fresh one keeps CodSpeed warmup runs from polluting the measured run.
    return {"type": "http", "method": method, "path": path, "root_path": "", "headers": [], "query_string": b""}


def dispatch(runner: ASGIRunner, app: ASGIApp, method: str, path: str) -> list[Message]:
    return runner.run(app, http_scope(method, path))


def test_routing_static_early(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture) -> None:
    messages = benchmark(dispatch, asgi_runner, LARGE_ROUTER, "GET", "/resources0")
    assert messages[0]["status"] == 200


def test_routing_static_late(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture) -> None:
    messages = benchmark(dispatch, asgi_runner, LARGE_ROUTER, "GET", "/resources29")
    assert messages[0]["status"] == 200


def test_routing_param_late(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture) -> None:
    messages = benchmark(dispatch, asgi_runner, LARGE_ROUTER, "GET", "/resources29/123/items/first")
    assert messages[0]["status"] == 200


def test_routing_miss(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture) -> None:
    messages = benchmark(dispatch, asgi_runner, LARGE_ROUTER, "GET", "/no/such/path")
    assert messages[0]["status"] == 404


def test_routing_method_not_allowed(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture) -> None:
    messages = benchmark(dispatch, asgi_runner, LARGE_ROUTER, "DELETE", "/resources29")
    assert messages[0]["status"] == 405


def test_routing_small_app(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture) -> None:
    messages = benchmark(dispatch, asgi_runner, SMALL_ROUTER, "GET", "/resources4/7")
    assert messages[0]["status"] == 200

from __future__ import annotations

from collections.abc import AsyncIterator
from dataclasses import dataclass

import pytest
from pytest_codspeed.plugin import BenchmarkFixture

from benchmarks._utils import ASGIRunner
from starlette.responses import StreamingResponse
from starlette.types import ASGIApp, Message, Receive, Scope, Send

KiB = 1024
MiB = 1024 * KiB


@dataclass(frozen=True)
class BenchmarkCase:
    id: str
    body_size: int
    chunk_size: int


CASES = (
    BenchmarkCase("1KiB-single", KiB, KiB),
    BenchmarkCase("1MiB-1KiB", MiB, KiB),
    BenchmarkCase("1MiB-64KiB", MiB, 64 * KiB),
    BenchmarkCase("1MiB-single", MiB, MiB),
)


class StreamingApp:
    def __init__(self, chunks: tuple[bytes, ...]) -> None:
        self.chunks = chunks

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        await StreamingResponse(iter_chunks(self.chunks))(scope, receive, send)


async def iter_chunks(chunks: tuple[bytes, ...]) -> AsyncIterator[bytes]:
    for chunk in chunks:
        yield chunk


def make_chunks(body_size: int, chunk_size: int) -> tuple[bytes, ...]:
    payload = b"x" * body_size
    return tuple(payload[offset : offset + chunk_size] for offset in range(0, body_size, chunk_size))


def http_scope() -> Scope:
    return {
        "type": "http",
        "asgi": {"version": "3.0", "spec_version": "2.5"},
        "http_version": "1.1",
        "method": "GET",
        "scheme": "http",
        "path": "/",
        "raw_path": b"/",
        "root_path": "",
        "query_string": b"",
        "headers": [],
        "client": ("127.0.0.1", 50000),
        "server": ("127.0.0.1", 80),
    }


def dispatch(runner: ASGIRunner, app: ASGIApp) -> list[Message]:
    return runner.run(app, http_scope())


@pytest.fixture(scope="module", autouse=True)
def warm_streaming(asgi_runner: ASGIRunner) -> None:
    app = StreamingApp((b"x",))
    for _ in range(100):
        dispatch(asgi_runner, app)


@pytest.mark.parametrize("case", CASES, ids=lambda case: case.id)
@pytest.mark.benchmark(max_time=0.5, max_rounds=1)
def test_streaming_response(asgi_runner: ASGIRunner, benchmark: BenchmarkFixture, case: BenchmarkCase) -> None:
    chunks = make_chunks(case.body_size, case.chunk_size)
    messages = benchmark.pedantic(dispatch, args=(asgi_runner, StreamingApp(chunks)), rounds=1)

    assert messages[0] == {"type": "http.response.start", "status": 200, "headers": []}
    assert messages[-1] == {"type": "http.response.body", "body": b"", "more_body": False}
    assert len(messages) == len(chunks) + 2
    assert sum(len(message.get("body", b"")) for message in messages[1:]) == case.body_size
    assert all(message.get("more_body") is True for message in messages[1:-1])
    benchmark.extra_info["body_bytes"] = case.body_size
    benchmark.extra_info["chunk_bytes"] = case.chunk_size
    benchmark.extra_info["chunks"] = len(chunks)

